declare(strict_types=1);require __DIR__.'/bootstrap.php';use Ogpn\Bot\{Bootstrap,Auth};$pdo=Bootstrap::pdo();$w=Auth::worker($pdo,'discovery.claim');$pdo->beginTransaction();$s=$pdo->query("SELECT id,crawl_id,tld,page_number FROM common_crawl_jobs WHERE status='pending' OR (status='reserved' AND reserved_until<UTC_TIMESTAMP()) ORDER BY created_at,id LIMIT 1 FOR UPDATE");$j=$s->fetch();if(!$j){$pdo->commit();Bootstrap::json(['job'=>null]);}$u=$pdo->prepare("UPDATE common_crawl_jobs SET status='reserved',reserved_by=?,reserved_until=DATE_ADD(UTC_TIMESTAMP(),INTERVAL 20 MINUTE),attempts=attempts+1 WHERE id=?");$u->execute([$w['worker_id'],$j['id']]);$pdo->commit();Bootstrap::json(['job'=>$j]);
